class WpfCopyCheck {
 static readonly BindingFlags Flags=BindingFlags.NonPublic|BindingFlags.Instance;
 static int count;
 static void Check(bool value,string title){if(!value)throw new Exception(title);count++;Console.WriteLine("PASS "+title);}
 static void Pump(){var frame=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Background,new Action(()=>frame.Continue=false));Dispatcher.PushFrame(frame);}
 static T[] All<T>(DependencyObject root) where T:DependencyObject {var result=new System.Collections.Generic.List<T>();for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);if(child is T)result.Add((T)child);result.AddRange(All<T>(child));}return result.ToArray();}
 static void Save(Window window,string file){var watch=Stopwatch.StartNew();while(watch.ElapsedMilliseconds<180){Pump();Thread.Sleep(10);}window.UpdateLayout();int w=(int)window.ActualWidth,h=(int)window.ActualHeight;var image=new RenderTargetBitmap(w,h,96,96,PixelFormats.Pbgra32);image.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using(var stream=File.Create(file))encoder.Save(stream);}
 static void SaveComposite(Window owner,Window dialog,string path){owner.UpdateLayout();dialog.UpdateLayout();var background=new RenderTargetBitmap((int)owner.ActualWidth,(int)owner.ActualHeight,96,96,PixelFormats.Pbgra32);background.Render(owner);var foreground=new RenderTargetBitmap((int)dialog.ActualWidth,(int)dialog.ActualHeight,96,96,PixelFormats.Pbgra32);foreground.Render(dialog);var visual=new DrawingVisual();using(var drawing=visual.RenderOpen()){drawing.DrawImage(background,new Rect(0,0,owner.ActualWidth,owner.ActualHeight));drawing.DrawImage(foreground,new Rect(dialog.Left-owner.Left,dialog.Top-owner.Top,dialog.ActualWidth,dialog.ActualHeight));}var image=new RenderTargetBitmap((int)owner.ActualWidth,(int)owner.ActualHeight,96,96,PixelFormats.Pbgra32);image.Render(visual);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using(var stream=File.Create(path))encoder.Save(stream);}
 static void CheckWorkspace(MainWindow window,ClientSession session,string root){session.State.AdvancedMode=true;typeof(MainWindow).GetMethod("ApplyInterface",Flags).Invoke(window,null);var page=typeof(MainWindow).GetMethod("Page",Flags);page.Invoke(window,new object[]{"Главная"});Pump();Check(All<Button>(window).Any(b=>Convert.ToString(b.Content)=="Глобальные горячие клавиши"),"advanced home keeps parameters card");Save(window,Path.Combine(root,"advanced-home.png"));page.Invoke(window,new object[]{"Zapret"});var until=DateTime.UtcNow.AddSeconds(10);while(!All<ComboBox>(window).Any(c=>c.Name.StartsWith("zapretOutputStrategy_"))&&DateTime.UtcNow<until){Pump();Thread.Sleep(10);}Check(All<ComboBox>(window).Any(c=>c.Name.StartsWith("zapretOutputStrategy_")&&c.Items.Count>0),"Zapret profile rows load real strategy catalog");Check(All<ComboBox>(window).Any(c=>c.Name.StartsWith("zapretOutputStrategy_")&&c.Items.Count>2),"cached profile catalog loads all strategies, not just placeholder");Check(new[]{"Новый профиль","Изменить","Удалить","Генератор стратегий","Редактор стратегий"}.All(t=>All<Button>(window).Any(b=>Convert.ToString(b.Content)==t)),"Zapret has profile tools and strategy tools");Save(window,Path.Combine(root,"zapret.png"));All<ComboBox>(window).Single(c=>c.Name=="zapretStrategySet").SelectedItem="ByeTube";Pump();Check(All<Button>(window).Any(b=>Convert.ToString(b.Content)=="Сохранить стратегию"),"ByeTube engine interface has real controls");All<ComboBox>(window).Single(c=>c.Name=="zapretStrategySet").SelectedItem="Zapret";Pump();page.Invoke(window,new object[]{"Редактор стратегий"});Save(window,Path.Combine(root,"advanced-editor.png"));session.State.AdvancedMode=false;typeof(MainWindow).GetMethod("ApplyInterface",Flags).Invoke(window,null);page.Invoke(window,new object[]{"Главная"});Pump();Check(window.Background!=null,"basic shell retains background with static patterned overlay");}
 static void RouteAction(MainWindow main,ClientSession session,RouteList route,bool save){Exception error=null;int before=session.State.Lists.Count;Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Background,new Action(()=>{try{var dialog=Application.Current.Windows.Cast<Window>().First(w=>w!=main);Check(dialog.WindowStyle==WindowStyle.None,"route editor uses glass chrome, not OS title bar");Check(typeof(MainWindow).GetField("modalVeil",Flags).GetValue(main)!=null,"modal opens cached blurred backdrop");Save(dialog,Path.Combine(session.Store.Root,"route-editor.png"));Save(main,Path.Combine(session.Store.Root,"route-blur.png"));SaveComposite(main,dialog,Path.Combine(session.Store.Root,"glass-preview.png"));var fields=All<TextBox>(dialog);fields.First(t=>!t.AcceptsReturn&&t.Text==(route==null?"Новый маршрут":route.Name)).Text="WPF проверка маршрута";fields.First(t=>t.AcceptsReturn).Text="wardogs.example.com\n104.18.124.108/32";Check(All<CheckBox>(dialog).First(c=>Convert.ToString(c.Content).StartsWith("Оригинальный движок")).Visibility==Visibility.Collapsed,"original-engine switch hidden for direct output");All<Button>(dialog).First(b=>Convert.ToString(b.Content)==(save?"Сохранить":"Отмена")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}catch(Exception ex){error=ex;Application.Current.Windows.Cast<Window>().First(w=>w!=main).Close();}}));var action=(System.Threading.Tasks.Task)typeof(MainWindow).GetMethod("RouteEditor",Flags).Invoke(main,new object[]{route});DateTime until=DateTime.UtcNow.AddSeconds(10);while(!action.IsCompleted&&DateTime.UtcNow<until){Pump();Thread.Sleep(10);}if(error!=null)throw error;Check(action.IsCompleted,"route dialog finishes without UI deadlock");Check(typeof(MainWindow).GetField("modalVeil",Flags).GetValue(main)==null,"closing modal removes its entire blurred layer");action.GetAwaiter().GetResult();Check(save?session.State.Lists.Count==before+1:session.State.Lists.Count==before,"route save/cancel preserves expected list count");}
 static void Wait(System.Threading.Tasks.Task task){var deadline=DateTime.UtcNow.AddSeconds(15);while(!task.IsCompleted&&DateTime.UtcNow<deadline){Pump();Thread.Sleep(10);}Check(task.IsCompleted,"asynchronous operation finishes");task.GetAwaiter().GetResult();}
 static void Click(MainWindow main,string caption){All<Button>(main).First(b=>Convert.ToString(b.Content)==caption).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var deadline=DateTime.UtcNow.AddSeconds(15);while((bool)typeof(MainWindow).GetField("busy",Flags).GetValue(main)&&DateTime.UtcNow<deadline){Pump();Thread.Sleep(10);}Pump();}
