  var page=typeof(MainWindow).GetMethod("Page",Flags);session.State.AdvancedMode=true;typeof(MainWindow).GetMethod("ApplyInterface",Flags).Invoke(main,null);
  page.Invoke(main,new object[]{"Маршрутизация"});Pump();var grid=All<DataGrid>(main).First(g=>g.Name=="routeGrid");Check(grid.Columns.Count==8,"routing includes status/name/count/source/output/TCP/UDP/DNS");Check(new[]{"Добавить","Удалить","Изменить","Объединить","↑","↓","Обновить список","Исключить приложения из всех правил","Захват процесса","Шаблоны игр","Пресеты","Применить DNS"}.All(t=>All<Button>(main).Any(b=>Convert.ToString(b.Content)==t)),"routing retains original actions");
  var original=session.State.Lists.ToArray();session.State.Lists.Clear();for(int i=0;i<1000;i++)session.State.Lists.Add(new RouteList{Name="Проверка "+i,Text="test"+i+".example.com",Target="direct",MatchMode="addresses"});var watch=Stopwatch.StartNew();page.Invoke(main,new object[]{"Маршрутизация"});Pump();main.UpdateLayout();watch.Stop();grid=All<DataGrid>(main).First(g=>g.Name=="routeGrid");Check(grid.Items.Count==1000,"routing accepts 1000 rules");Check(All<DataGridRow>(grid).Length<60,"only visible route rows are materialized");Check(watch.ElapsedMilliseconds<2000,"1000-route page opens without multi-second freeze ("+watch.ElapsedMilliseconds+" ms)");grid.ScrollIntoView(grid.Items[999]);Pump();Check(All<Button>(grid).Any(b=>Convert.ToString(b.Content)=="Проверка 999"),"virtualized route controls work after scrolling");session.State.Lists.Clear();session.State.Lists.AddRange(original);page.Invoke(main,new object[]{"Маршрутизация"});Pump();Save(main,Path.Combine(root,"routes.png"));
