  page.Invoke(main,new object[]{"Редактор стратегий"});var deadline=DateTime.UtcNow.AddSeconds(10);while(!All<ComboBox>(main).Any(c=>c.Name=="wpfStrategyBasis"&&c.Items.Count>0)&&DateTime.UtcNow<deadline){Pump();Thread.Sleep(10);}var blocks=All<ComboBox>(main).First(c=>c.Name=="wpfParameterBlock");int countBlocks=blocks.Items.Count;Click(main,"Добавить блок");Check(blocks.Items.Count==countBlocks+1,"editor adds a full configuration block");Click(main,"Удалить блок");Check(blocks.Items.Count==countBlocks,"editor removes the selected block");var argument=All<ComboBox>(main).First(c=>c.Name=="wpfParameterName");argument.SelectedItem=argument.Items.Cast<string>().First(t=>t.EndsWith("--dpi-desync"));Pump();var choices=All<ComboBox>(main).First(c=>c.Name=="wpfParameterChoices");choices.SelectedItem="fake";Pump();Check(All<TextBox>(main).First(t=>t.Name=="wpfParameterValue").Visibility==Visibility.Collapsed,"manual input hidden for ready-made choice");Check(All<TextBlock>(main).Any(t=>t.Text.Contains("поддельный пакет")),"editor explains the selected mode");choices.SelectedIndex=0;Pump();Check(All<TextBox>(main).First(t=>t.Name=="wpfParameterValue").Visibility==Visibility.Visible,"manual input only shown on demand");Check(All<Button>(main).First(b=>Convert.ToString(b.Content)=="Выбрать файл из BIN").Visibility==Visibility.Collapsed,"BIN picker hidden for non-file arguments");argument.SelectedItem=argument.Items.Cast<string>().First(t=>t.EndsWith("--dpi-desync-fake-quic"));Pump();Check(All<Button>(main).First(b=>Convert.ToString(b.Content)=="Выбрать файл из BIN").Visibility==Visibility.Visible,"BIN picker shown for payload argument");Check(StrategyParameterEditor.PayloadFiles(session.Zapret.DirectoryPath).Length>0,"BIN choices use files actually bundled with engine");Save(main,Path.Combine(root,"editor.png"));
