 [STAThread]static int Main(string[] args){try{string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Mcrf.Wpf.Program.LoadTheme(app);SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));var window=new MainWindow(new[]{"--data",root});window.Show();DateTime until=DateTime.UtcNow.AddSeconds(20);while(typeof(MainWindow).GetField("session",Flags).GetValue(window)==null&&DateTime.UtcNow<until){Pump();Thread.Sleep(10);}var session=(ClientSession)typeof(MainWindow).GetField("session",Flags).GetValue(window);Check(session!=null,"WPF opens isolated session");Check(session.Store.Root==root,"separate data root, no user profile migration");Check(!session.Core.Running&&!session.Zapret.Running&&!session.Telegram.Running,"startup launches no network engines");
  var page=typeof(MainWindow).GetMethod("Page",Flags);foreach(string name in new[]{"Главная","Серверы VPN","Маршрутизация","WARP","Telegram WS","Zapret","hosts","Журнал","Обновления","Генератор стратегий","Редактор стратегий"}){var watch=Stopwatch.StartNew();page.Invoke(window,new object[]{name});Pump();Check(All<Grid>(window).Length>0,"WPF page renders: "+name+" in "+watch.ElapsedMilliseconds+" ms");if(name=="Маршрутизация")Check(All<DataGrid>(window).All(g=>g.EnableRowVirtualization&&g.EnableColumnVirtualization),"route tables use virtualization");}
  until=DateTime.UtcNow.AddSeconds(15);while(All<ComboBox>(window).All(c=>c.Items.Count==0)&&DateTime.UtcNow<until){Pump();Thread.Sleep(10);}Check(All<ComboBox>(window).Any(c=>c.Items.Count>0),"strategy bases load asynchronously");var bases=All<ComboBox>(window).First(c=>c.DisplayMemberPath=="ShortName");Check(bases.Items.Count>0&&bases.SelectedItem is ZapretStrategy,"strategies bind displayed properties, not fields");Check(All<CheckBox>(window).Any(c=>Convert.ToString(c.Content)=="Аргумент есть в блоке"&&c.IsChecked==true),"editor marks existing argument");Check(All<TextBox>(window).Any(t=>t.IsReadOnly&&t.Text.Contains("--filter-")),"editor previews selected block");Check(All<Button>(window).Any(b=>Convert.ToString(b.Content)=="Отмена"),"editor has Cancel");
  foreach(var size in new[]{new Size(1080,700),new Size(1366,865)}){window.Width=size.Width;window.Height=size.Height;Pump();window.UpdateLayout();Check(All<Button>(window).Where(b=>b.IsVisible).All(b=>b.ActualWidth>20&&b.ActualHeight>10),"controls remain usable at "+size);Save(window,Path.Combine(root,"editor-"+size.Width+".png"));}
var argument=All<ComboBox>(window).First(c=>c.Name=="wpfParameterName");argument.SelectedItem=argument.Items.Cast<string>().First(t=>t.EndsWith("--dpi-desync-cutoff"));Pump();var choices=All<ComboBox>(window).First(c=>c.Name=="wpfParameterChoices");choices.SelectedIndex=0;var value=All<TextBox>(window).First(t=>t.Name=="wpfParameterValue");value.Text="n4";All<Button>(window).First(b=>Convert.ToString(b.Content)=="Добавить / изменить").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Check(Convert.ToString(argument.SelectedItem).StartsWith("✓ "),"adding argument marks it present");Check(All<TextBox>(window).First(t=>t.Name=="wpfBlockPreview").Text.Contains("--dpi-desync-cutoff=n4"),"selected-block preview reflects changed value");All<Button>(window).First(b=>Convert.ToString(b.Content)=="Удалить аргумент").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Check(Convert.ToString(argument.SelectedItem).StartsWith("○ "),"removing argument clears presence marker");value.Text="n4";All<Button>(window).First(b=>Convert.ToString(b.Content)=="Добавить / изменить").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));All<TextBox>(window).First(t=>t.Name=="wpfStrategyName").Text="WPF проверенная копия";All<Button>(window).First(b=>Convert.ToString(b.Content)=="Сохранить копию").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));until=DateTime.UtcNow.AddSeconds(15);while((bool)typeof(MainWindow).GetField("busy",Flags).GetValue(window)&&DateTime.UtcNow<until){Pump();Thread.Sleep(10);}var copies=CustomStrategies.Read(session.Zapret.DirectoryPath);Check(copies.Any(d=>d.Name=="WPF проверенная копия"&&d.BatConfig.Contains("--dpi-desync-cutoff=n4")),"WPF saves structured fork without touching basis");var catalogTask=session.Strategies();while(!catalogTask.IsCompleted){Pump();Thread.Sleep(10);}Check(catalogTask.Result.Any(c=>copies.Any(d=>d.Id==c.Id)),"WPF copy is available in shared strategy catalog");int copyCount=copies.Count();All<Button>(window).First(b=>Convert.ToString(b.Content)=="Отмена").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Check((string)typeof(MainWindow).GetField("current",Flags).GetValue(window)=="Zapret"&&CustomStrategies.Read(session.Zapret.DirectoryPath).Count()==copyCount,"editor Cancel returns to Zapret and leaves saved copies intact");
  typeof(MainWindow).GetField("busy",Flags).SetValue(window,true);RouteAction(window,session,null,true);var created=session.State.Lists.Last();string originalName=created.Name;RouteAction(window,session,created,false);Check(created.Name==originalName,"route Cancel never mutates original object");typeof(MainWindow).GetField("busy",Flags).SetValue(window,false);page.Invoke(window,new object[]{"Главная"});Pump();Save(window,Path.Combine(root,"home.png"));CheckWorkspace(window,session,root);CheckParity(window,session,root);for(int i=0;i<3;i++){window.WindowState=WindowState.Maximized;Pump();window.WindowState=WindowState.Normal;Pump();}Check(window.WindowState==WindowState.Normal,"standard WPF maximize/restore returns cleanly");Check(!session.Core.Running&&!session.Zapret.Running&&!session.Telegram.Running,"UI checks never start network engines");window.Close();until=DateTime.UtcNow.AddSeconds(10);while(window.IsVisible&&DateTime.UtcNow<until){Pump();Thread.Sleep(10);}Check(!window.IsVisible,"closing completes owned session cleanup");Console.WriteLine("OK "+count+" checks");app.Shutdown();return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
